    return try FfiConverterTypeFfiVectorF64.lift(pointer)
}

public func FfiConverterTypeFfiVectorF64_lower(_ value: FfiVectorF64) -> UnsafeMutableRawPointer {
    return FfiConverterTypeFfiVectorF64.lower(value)
